css:
body{font-family:"Segoe UI Variable","Segoe UI",-apple-system,BlinkMacSystemFont,system-ui,sans-serif;}
[data-chat-header]{--foreground:#FFFFFF;--color-foreground:#FFFFFF;--contrast-foreground:#FFFFFF;--muted-foreground:#D2D3EC;--color-muted-foreground:#D2D3EC;--contrast-muted-foreground:#D2D3EC;--placeholder:#D2D3EC;--color-placeholder:#D2D3EC;--accent:#5E5F92;--color-accent:#5E5F92;--accent-foreground:#FFFFFF;--color-accent-foreground:#FFFFFF;--secondary:#5E5F92;--color-secondary:#5E5F92;--secondary-foreground:#FFFFFF;--color-secondary-foreground:#FFFFFF;--muted:#5E5F92;--color-muted:#5E5F92;--border:#6E6FA3;--color-border:#6E6FA3;--input:#6E6FA3;--color-input:#6E6FA3;color:#FFFFFF;}
.dark [data-chat-header]{--accent:#4A4B75;--color-accent:#4A4B75;--secondary:#4A4B75;--color-secondary:#4A4B75;--muted:#4A4B75;--color-muted:#4A4B75;--muted-foreground:#C4C5DE;--color-muted-foreground:#C4C5DE;--contrast-muted-foreground:#C4C5DE;--border:#4A4B75;--color-border:#4A4B75;--input:#4A4B75;--color-input:#4A4B75;}
[data-chat-header] [data-slot="button"][data-pressed],[data-chat-header] [data-toolbar-control][data-pressed],[data-chat-header] [aria-pressed="true"]{background-color:rgba(255,255,255,.22)!important;color:#FFFFFF!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"],[data-thread-item]{border-radius:4px!important;}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:6px!important;border:1px solid var(--border)!important;}
[data-slot="tooltip-popup"]{border-radius:4px!important;}
[data-user-message-bubble]{border-radius:6px!important;}
.chat-markdown-codeblock{border-radius:4px!important;border:1px solid var(--border);}
[data-slot="composer-host"]{border-radius:4px!important;border:1px solid var(--border)!important;box-shadow:0 1px 2px rgba(0,0,0,.12)!important;border-bottom:2px solid transparent!important;transition:border-color .15s;}
[data-slot="composer-host"]:focus-within{border-bottom-color:var(--primary)!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 12%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#FFFFFF!important;box-shadow:inset 0 0 0 1px #616161!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#616161!important;}
:root:not(.dark) [data-slot="switch"][data-checked]{background:#5B5FC7!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
.dark [data-slot="switch"][data-unchecked]{background:transparent!important;box-shadow:inset 0 0 0 1px #ADADAD!important;}
.dark [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#ADADAD!important;}
.dark [data-slot="switch"][data-checked]{background:#7F85F5!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#141414!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 22%,transparent);border-radius:999px;border:3px solid transparent;background-clip:padding-box;}
